try:
    print('>>> f = hasattr')
    print('>>> x = b""')
    print('>>> y = 3')
    print('>>> f(x, y)')
    f = hasattr
    x = b""
    y = 3
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
